 private static void shot(String name){try{Files.createDirectories(OUT);try(var im=Screenshot.takeScreenshot(Minecraft.getInstance().getMainRenderTarget())){im.writeToFile(OUT.resolve(name+(COPY_MODE && (name.equals("loan-shark-report") || name.equals("loan-shark-report-small") || name.equals("loan-shark-claimed"))?"-copy":"")+".png"));}}catch(Exception e){error=e.toString();}}
