  try{var f=LoanScreen.class.getDeclaredField("state");f.setAccessible(true);var state=(net.minecraft.nbt.CompoundTag)f.get(mc.screen);if(state.getInt("mode")==0)for(var raw:state.getList("rows",10)){var row=(net.minecraft.nbt.CompoundTag)raw;check(row.getDouble("mastery")>=0,"Unfinished skill listed in Loan");var skill=SkillAPI.getSkillRegistry().get(net.minecraft.resources.ResourceLocation.parse(row.getString("skill")));check(SkillAPI.getSkillsFrom(mc.player).getSkill(skill).filter(i->i.getMastery()>=0 && !i.isTemporarySkill()).isPresent(),"Unowned skill listed in Loan");}}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}
