  if(phase==12 && ++tick>10){try{var f=LoanScreen.class.getDeclaredField("state");f.setAccessible(true);check(((net.minecraft.nbt.CompoundTag)f.get(mc.screen)).getInt("count")==0,"Claimed gift remains in Report");}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}shot("loan-shark-claimed");if(!DEATH_REVIEW){mc.stop();return;}phase=200;tick=0;server(p->{p.removeAllEffects();p.setHealth(p.getMaxHealth());var awake=TensuraStorages.getExistenceFrom(p);awake.setSleepModeTime(-1);awake.setAura(EnergyHelper.getMaxAura(p));awake.setMagicule(EnergyHelper.getMaxMagicule(p));awake.markDirty();var e=new net.minecraft.world.entity.monster.Husk(EntityType.HUSK,p.serverLevel());e.setNoAi(true);e.setNoGravity(true);e.setPos(p.position().add(3,0,0));e.setCustomName(net.minecraft.network.chat.Component.literal("Mortal Borrower"));p.serverLevel().addFreshEntity(e);TensuraStorages.getExistenceFrom(e).setPermanentOwner(p.getUUID());EnergyHelper.setBaseMaxEP(e,100000);borrower=e.getUUID();check(LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName())!=null,"Death fixture loan failed: owns="+LoanShark.owns(p)+", eligible="+LoanShark.eligible(p,e)+", source="+SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).isPresent());LoanShark.open(p,1);});}
  if(phase==200 && mc.screen instanceof LoanScreen && ++tick>25){shot("loan-shark-before-death");phase=201;tick=0;server(p->{var e=LoanShark.resolve(p.server,borrower);e.hurt(e.damageSources().genericKill(),Float.MAX_VALUE);});return;}
